"use client";

import React, { useEffect, useState } from "react";
import ScrambleText from "./ScrambleText";
import GridDistortion from "./GridDistortion";

const events = [
  { image: "/Event/download (13).jpg",                       title: "VivaTech 2025", subtitle: "In Paris" },
  { image: "/Event/download (14).jpg",                       title: "VivaTech 2025", subtitle: "In Paris" },
  { image: "/Event/download (15).jpg",                       title: "VivaTech 2025", subtitle: "In Paris" },
  { image: "/Event/download - 2026-06-07T111512.540.png",    title: "VivaTech 2025", subtitle: "In Paris" },
];

// Visual position 0 = front/top card, 3 = back/bottom card
const ROT_BASE    = [0,  8, 16, 24];   // rotation at rest
const ROT_HOVER   = [0, 15, 28, 41];   // rotation when front card is hovered (fan opens wider)
const GRAYSCALES  = [0,  60, 85, 100]; // grayscale % per position (front = full color)
const OPACITIES   = [1, 1, 1, 1];

const CARD_W = 460;
const CARD_H = 520;

export default function GlobalEvents() {
  // order[i] = which event image sits at visual position i (0=front)
  const [order, setOrder]             = useState([0, 1, 2, 3]);
  const [frontHovered, setFrontHovered] = useState(false);
  // track which back card is being hovered for a subtle lift hint
  const [backHint, setBackHint]       = useState<number | null>(null);

  useEffect(() => {
    if (frontHovered || backHint !== null) return;

    const timer = window.setInterval(() => {
      setOrder((prev) => {
        const [front, ...rest] = prev;
        return [...rest, front];
      });
    }, 2000);

    return () => window.clearInterval(timer);
  }, [frontHovered, backHint]);

  /** Move any back card to the front of the deck */
  const bringToFront = (visualPos: number) => {
    if (visualPos === 0) return;
    setOrder(prev => {
      const next = [...prev];
      const [card] = next.splice(visualPos, 1);
      return [card, ...next];
    });
  };

  return (
    <section
      className="section-reveal global-events-reveal relative w-full py-20 md:py-28 px-5 md:px-20 bg-[#f6f7f9] border-t border-slate-100 text-slate-800"
      style={{ overflowX: "clip", overflowY: "visible" }}
      aria-labelledby="global-events-heading"
    >
      {/* Subtle grid background */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        <div className="absolute inset-0 bg-[linear-gradient(to_right,#cbd5e1_1px,transparent_1px),linear-gradient(to_bottom,#cbd5e1_1px,transparent_1px)] bg-[size:4rem_4rem] [mask-image:radial-gradient(ellipse_60%_50%_at_50%_50%,#000_70%,transparent_100%)] opacity-[0.12]" />
      </div>

      <div className="max-w-[1400px] mx-auto relative z-10 flex flex-col lg:flex-row items-center gap-16 lg:gap-20">

        {/* ── LEFT: Text Block ── */}
        <div className="reveal-item reveal-left reveal-delay-1 flex-1 flex flex-col items-start text-left max-w-xl lg:max-w-none lg:w-[45%]">
          <span className="font-sans text-sm font-bold uppercase tracking-[0.15em] text-blue-600 mb-4 block">
            <ScrambleText text="Global Events" />
          </span>
          <h2
            id="global-events-heading"
            className="font-sans text-3xl md:text-5xl font-extrabold leading-tight tracking-tight mb-6"
          >
            <span className="text-transparent bg-clip-text bg-gradient-to-b from-[#aebcff] via-[#2546c7] to-[#09164f]">
              Global Events
            </span>
          </h2>
          <p className="font-sans text-base md:text-lg leading-relaxed text-slate-600">
            Experience CodeMoly on the world stage at VivaTech 2025 and other
            premier global tech events. We connect with innovators, startups,
            and industry leaders to share ideas, build partnerships, and
            showcase our cutting-edge solutions. At CodeMoly, we&apos;re more
            than just a top-tier development firm — we&apos;re a global
            community of passionate developers and tech professionals dedicated
            to learning, growing, and creating impactful success stories.
          </p>
        </div>

        {/* ── RIGHT: Card Deck (playing-card fan) ── */}
        <div className="reveal-item reveal-right reveal-delay-2 flex-1 flex justify-center lg:justify-end items-end pb-8">
          {/*
            Container holds all cards stacked at bottom-left.
            Cards rotate around their own bottom-center pivot,
            fanning out clockwise so back cards peek to the right.
            Container is intentionally wider than a single card to
            accommodate the fanned cards without clipping.
          */}
          <div
            className="relative select-none"
            style={{ 
              width: "var(--card-container-w, 640px)", 
              height: "var(--card-container-h, 540px)" 
            }}
          >
            {order.map((imageIdx, visualPos) => {
              const isFront   = visualPos === 0;
              const rot       = frontHovered ? ROT_HOVER[visualPos] : ROT_BASE[visualPos];
              const grayscale = GRAYSCALES[visualPos];
              const opacity   = OPACITIES[visualPos];
              const zIndex    = events.length - visualPos + 1;
              const isBackHint = backHint === visualPos && !isFront;

              return (
                <div
                  key={imageIdx}
                  /* Front card: detect hover to fan back cards */
                  onMouseEnter={() => {
                    if (isFront) setFrontHovered(true);
                    else setBackHint(visualPos);
                  }}
                  onMouseLeave={() => {
                    if (isFront) setFrontHovered(false);
                    else setBackHint(null);
                  }}
                  onClick={() => bringToFront(visualPos)}
                  style={{
                    position:        "absolute",
                    bottom:          0,
                    left:            0,
                    width:           "var(--card-w, 460px)",
                    height:          "var(--card-h, 520px)",
                    borderRadius:    18,
                    overflow:        "hidden",
                    transformOrigin: "bottom center",
                    transform: isBackHint
                      ? `rotate(${rot + 4}deg) scale(0.97)`   // subtle lift hint on back-card hover
                      : `rotate(${rot}deg)`,
                    filter:    `grayscale(${grayscale}%)`,
                    opacity,
                    zIndex,
                    cursor:    isFront ? "default" : "pointer",
                    transition:
                      "transform 0.5s cubic-bezier(0.34,1.56,0.64,1), " +
                      "filter 0.4s ease, " +
                      "opacity 0.4s ease, " +
                      "box-shadow 0.35s ease",
                    boxShadow: isFront
                      ? "0 28px 60px rgba(0,0,0,0.28), 0 8px 20px rgba(0,0,0,0.16)"
                      : "0 10px 30px rgba(0,0,0,0.14)",
                  }}
                >
                  <GridDistortion
                    imageSrc={events[imageIdx].image}
                    className="w-full h-full object-cover block"
                    grid={12}
                    mouse={0.18}
                    strength={0.15}
                    relaxation={0.9}
                  />

                  {/* Gradient overlay — stronger for non-front cards to accentuate the "behind" feel */}
                  <div
                    style={{
                      position: "absolute",
                      inset: 0,
                      background: isFront
                        ? "linear-gradient(to top, rgba(0,0,0,0.72) 0%, rgba(0,0,0,0.18) 45%, transparent 100%)"
                        : "linear-gradient(to top, rgba(0,0,0,0.82) 0%, rgba(0,0,0,0.35) 60%, rgba(0,0,0,0.12) 100%)",
                      pointerEvents: "none",
                    }}
                  />

                  {/* Text label — always visible on every card (readable through blur on back cards) */}
                  <div
                    style={{
                      position:      "absolute",
                      bottom:        0,
                      left:          0,
                      right:         0,
                      padding:       "24px 28px",
                      pointerEvents: "none",
                    }}
                  >
                    <p
                      style={{
                        fontFamily:  "var(--font-sans, sans-serif)",
                        fontSize:    isFront ? 22 : 18,
                        fontWeight:  800,
                        color:       "#fff",
                        lineHeight:  1.2,
                        letterSpacing: "-0.01em",
                        margin:      0,
                      }}
                    >
                      {events[imageIdx].title}
                    </p>
                    <p
                      style={{
                        fontFamily:    "var(--font-sans, sans-serif)",
                        fontSize:      12,
                        fontWeight:    700,
                        color:         "#93c5fd",
                        textTransform: "uppercase",
                        letterSpacing: "0.12em",
                        marginTop:     6,
                      }}
                    >
                      {events[imageIdx].subtitle}
                    </p>
                  </div>

                  {/* Click hint ring on back cards */}
                  {isBackHint && (
                    <div
                      style={{
                        position:     "absolute",
                        inset:        0,
                        borderRadius: 18,
                        boxShadow:    "inset 0 0 0 2px rgba(96,165,250,0.7)",
                        pointerEvents:"none",
                      }}
                    />
                  )}
                </div>
              );
            })}
          </div>
        </div>

      </div>
    </section>
  );
}
