"use client";

import React, { useState, useEffect } from "react";
import { Menu, X } from "lucide-react";

interface NavigationItem {
  label: string;
  link: string;
}

interface NavbarProps {
  navigation: NavigationItem[];
  logoUrl?: string | null;
  logoAlt?: string;
  logoTranslateY?: number;
  ctaLabel?: string;
  ctaLink?: string;
  showCta?: boolean;
  mobileMenuFooter?: string;
}

export default function Navbar({
  navigation,
  logoUrl,
  logoAlt = "CodeMoly",
  logoTranslateY = 2,
  ctaLabel = "Start a project",
  ctaLink = "#",
  showCta = true,
  mobileMenuFooter = "CODEMOLY AI LABS",
}: NavbarProps) {
  const [isOpen, setIsOpen] = useState(false);

  // Prevent background scroll when menu is open
  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "";
    }
    return () => {
      document.body.style.overflow = "";
    };
  }, [isOpen]);

  return (
    <>
      <nav className="navbar" aria-label="Primary navigation">
        {/* Left side: Hamburger (mobile only) + Logo */}
        <div className="flex items-center gap-3">
          <button
            onClick={() => setIsOpen(true)}
            className="flex items-center justify-center w-9 h-9 rounded-lg bg-white/10 hover:bg-white/15 border border-white/20 text-white transition-all active:scale-95 md:hidden"
            aria-label="Open navigation menu"
          >
            <Menu className="w-5 h-5" />
          </button>
          
          <div className="hidden md:block">
            <a className="brand flex-shrink-0" href="/" aria-label="CodeMoly home">
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src={logoUrl || "/CodeMoly White Logo.svg"}
                alt={logoAlt}
                className="h-[20px] w-auto select-none pointer-events-none flex-shrink-0"
                style={{ transform: `translateY(${logoTranslateY}px)` }}
              />
            </a>
          </div>
        </div>

        {/* Desktop nav links */}
        <div className="nav-links">
          {navigation.map((item, idx) => (
            <a
              key={idx}
              href={item.link && item.link.startsWith("#") ? (item.link === "#" ? "/" : `/${item.link}`) : (item.link || "/")}
              className="font-medium text-white/90 hover:text-white transition-colors"
            >
              {item.label}
            </a>
          ))}
        </div>

        {/* Actions wrapper */}
        {showCta && (
          <div className="nav-actions flex items-center gap-4">
            <div className="cta-contact-wrapper">
              <a
                href={ctaLink}
                className="cta-contact"
                style={{ width: "190px", height: "44px", fontSize: "12px", letterSpacing: "1.5px" }}
              >
                {ctaLabel}
              </a>
            </div>
          </div>
        )}
      </nav>

      {/* Mobile Menu Drawer Overlay */}
      <div
        className={`fixed inset-0 z-[100] bg-[#09102a]/95 backdrop-blur-xl flex flex-col justify-between transition-all duration-500 ease-out md:hidden ${
          isOpen ? "translate-y-0 opacity-100" : "-translate-y-full opacity-0"
        }`}
      >
        {/* Drawer Header */}
        <div className="flex items-center justify-between p-6 border-b border-white/10">
          <a className="brand" href="/" onClick={() => setIsOpen(false)} aria-label="CodeMoly home">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img
              src={logoUrl || "/CodeMoly White Logo.svg"}
              alt={logoAlt}
              className="h-[20px] w-auto select-none pointer-events-none"
            />
          </a>
          <button
            onClick={() => setIsOpen(false)}
            className="flex items-center justify-center w-10 h-10 rounded-lg bg-white/10 hover:bg-white/15 border border-white/20 text-white transition-all active:scale-95"
            aria-label="Close navigation menu"
          >
            <X className="w-6 h-6" />
          </button>
        </div>

        {/* Drawer Content */}
        <div className="flex-1 flex flex-col justify-center items-center gap-8 p-8">
          <div className="flex flex-col items-center gap-4 w-full max-w-[240px]">
            {navigation.map((item, idx) => (
              <a
                key={idx}
                href={item.link && item.link.startsWith("#") ? (item.link === "#" ? "/" : `/${item.link}`) : (item.link || "/")}
                onClick={() => setIsOpen(false)}
                className="w-full text-center font-sans text-xl font-bold transition-all duration-200 py-2.5 px-6 rounded-full text-white/80 hover:text-white hover:bg-white/5"
              >
                {item.label}
              </a>
            ))}
          </div>

          {showCta && (
            <div className="cta-contact-wrapper w-full max-w-[280px] mt-8">
              <a
                href={ctaLink}
                onClick={() => setIsOpen(false)}
                className="cta-contact w-full text-center"
                style={{ height: "50px", fontSize: "14px", letterSpacing: "1.5px" }}
              >
                {ctaLabel}
              </a>
            </div>
          )}
        </div>

        {/* Drawer Footer */}
        <div className="p-6 border-t border-white/10 text-center">
          <span className="text-xs text-white/40 tracking-wider">{mobileMenuFooter}</span>
        </div>
      </div>
    </>
  );
}
